import ast,subprocess,collections,re
files=subprocess.check_output(['git','ls-files','*.py']).decode().split()
classes=[] # (name,file,bases,lineno)
for f in files:
    try: t=ast.parse(open(f).read())
    except Exception as e: print("ERR",f,e); continue
    for n in ast.walk(t):
        if isinstance(n,ast.ClassDef):
            bs=[]
            for b in n.bases:
                s=ast.unparse(b); bs.append(s.split('.')[-1].split('[')[0])
            classes.append((n.name,f,bs,n.lineno))
istest=lambda f: bool(re.search(r'(^|/)(tests?/|test_[^/]*\.py$|[^/]*_test\.py$)',f))
found={'StockController'}; ch=True
while ch:
    ch=False
    for c in classes:
        if c[0] not in found and set(c[2])&found: found.add(c[0]); ch=True
for c in sorted(classes,key=lambda c:c[1]):
    if set(c[2])&found and c[0]!='StockController':
        print(("TEST " if istest(c[1]) else "")+f"{c[0]}({', '.join(c[2])})  {c[1]}:{c[3]}")
# dup names
cnt=collections.Counter(c[0] for c in classes)
print("dups among found:",[n for n in found if cnt[n]>1])
EOF
